const userId = String($json.user_id || '').trim();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if (!uuid.test(userId)) throw new Error('Renseignez un UUID Mailflow valide dans Configurer utilisateur.');
if (typeof $json.test_mode !== 'boolean') throw new Error('test_mode doit être un booléen.');
if (typeof $json.classify_in_test_mode !== 'boolean') throw new Error('classify_in_test_mode doit être un booléen.');
return [{ json: { user_id: userId, test_mode: $json.test_mode, classify_in_test_mode: $json.classify_in_test_mode } }];

const state = $('Lire curseur FastAPI').first().json;
const config = $('Configurer utilisateur').first().json;
const response = $json;
if (response.statusCode !== 200) throw new Error(`Gmail messages.list TEST a répondu HTTP ${response.statusCode}.`);
const messages = Array.isArray(response.body?.messages) ? response.body.messages : [];
if (messages.length > 50) throw new Error('Le mode TEST a reçu plus de 50 identifiants Gmail.');
const sync = { user_id: state.user_id, cursor_before: state.cursor || null, cursor_after: null, mode: 'test', test_mode: true, classify_in_test_mode: config.classify_in_test_mode === true };
const ids = [...new Set(messages.map((message) => typeof message?.id === 'string' ? message.id.trim() : '').filter(Boolean))];
if (ids.length === 0) return [{ json: { _empty: true, _sync: sync } }];
return ids.map((id) => ({ json: { gmail_message_id: id, attempt: 0, _sync: sync } }));

const state = $('Réserver synchronisation FastAPI').first().json;
const ids = new Set();
let cursorAfter = null;
for (const item of $input.all()) {
  const response = item.json;
  if (response.statusCode !== 200) throw new Error(`Gmail history.list a répondu HTTP ${response.statusCode}. Le curseur reste inchangé.`);
  const body = response.body || {};
  if (typeof body.historyId === 'string' && body.historyId.trim()) cursorAfter = body.historyId.trim();
  for (const event of Array.isArray(body.history) ? body.history : []) {
    for (const added of Array.isArray(event.messagesAdded) ? event.messagesAdded : []) {
      const id = typeof added?.message?.id === 'string' ? added.message.id.trim() : '';
      if (id) ids.add(id);
    }
  }
}
if (!cursorAfter) throw new Error('Gmail history.list n’a pas fourni de historyId final.');
const sync = { user_id: state.user_id, execution_id: state.execution_id, idempotency_key: `gmail-sync:${$execution.id}`, cursor_before: state.cursor, cursor_after: cursorAfter, mode: 'incremental', test_mode: false };
if (ids.size === 0) return [{ json: { _empty: true, _sync: sync } }];
return [...ids].map((id) => ({ json: { gmail_message_id: id, attempt: 0, _sync: sync } }));

const state = $('Réserver synchronisation FastAPI').first().json;
const profile = $('Lire profil Gmail').first().json;
const cursorAfter = typeof profile.historyId === 'string' ? profile.historyId.trim() : '';
if (!cursorAfter) throw new Error('Le profil Gmail n’a pas fourni de historyId.');
const ids = new Set();
for (const item of $input.all()) {
  if (item.json.statusCode !== 200) throw new Error(`Gmail messages.list a répondu HTTP ${item.json.statusCode}.`);
  for (const message of Array.isArray(item.json.body?.messages) ? item.json.body.messages : []) {
    const id = typeof message?.id === 'string' ? message.id.trim() : '';
    if (id) ids.add(id);
  }
}
const sync = { user_id: state.user_id, execution_id: state.execution_id, idempotency_key: `gmail-sync:${$execution.id}`, cursor_before: state.cursor || null, cursor_after: cursorAfter, mode: state.cursor ? 'recovery' : 'initial', test_mode: false };
if (ids.size === 0) return [{ json: { _empty: true, _sync: sync } }];
return [...ids].map((id) => ({ json: { gmail_message_id: id, attempt: 0, _sync: sync } }));

const item = $json;
if (!item.gmail_message_id || !item._sync) throw new Error('Élément Gmail incomplet dans la file.');
return [{ json: { ...item, attempt: Number.isInteger(item.attempt) ? item.attempt : 0 } }];

const request = $('Préparer requête détail').item.json;
const response = $json;
const statusCode = Number(response.statusCode || 0);
const error = response.body?.error || {};
const reasons = Array.isArray(error.errors) ? error.errors.map((entry) => String(entry?.reason || '')) : [];
const errorMessage = String(error.message || '');
const quotaReason = reasons.some((reason) => ['rateLimitExceeded', 'userRateLimitExceeded', 'quotaExceeded'].includes(reason));
const quotaText = /quota|rate.?limit/i.test(errorMessage);
const notFound = statusCode === 404;
const retryable = statusCode === 429 || (statusCode === 403 && (quotaReason || quotaText));
const attempt = Number.isInteger(request.attempt) ? request.attempt : 0;
const jitter = Math.random();
const backoffSeconds = Math.min(32, 2 ** attempt) + jitter;
return [{ json: { ...request, status_code: statusCode, not_found: notFound, retryable, retry_reasons: reasons, error_message: errorMessage, backoff_seconds: backoffSeconds, gmail_response: response.body || {} } }];

const item = $json;
const source = item.gmail_response || {};
const headers = Array.isArray(source.payload?.headers) ? source.payload.headers : [];
const header = (name) => {
  const found = headers.find((entry) => String(entry?.name || '').toLowerCase() === name.toLowerCase());
  return typeof found?.value === 'string' ? found.value.trim() : '';
};
const decode = (value) => {
  if (typeof value !== 'string' || !value) return '';
  const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
  return Buffer.from(normalized, 'base64').toString('utf8');
};
const plain = [];
const html = [];
const visit = (part) => {
  if (!part || typeof part !== 'object') return;
  const mime = String(part.mimeType || '').toLowerCase();
  const filename = String(part.filename || '').trim();
  const data = part.body?.data;
  if (!filename && mime === 'text/plain' && data) plain.push(decode(data));
  if (!filename && mime === 'text/html' && data) html.push(decode(data));
  for (const child of Array.isArray(part.parts) ? part.parts : []) visit(child);
};
visit(source.payload);
const sender = header('From');
const receivedAt = /^\d+$/.test(String(source.internalDate || '')) ? new Date(Number(source.internalDate)) : new Date(header('Date'));
if (!source.id || !source.threadId || !sender || Number.isNaN(receivedAt.getTime())) throw new Error(`Message Gmail ${item.gmail_message_id} incomplet.`);
const recipients = [...new Set([header('To'), header('Cc'), header('Bcc')].filter(Boolean))];
return [{ json: {
  _sync: item._sync, gmail_message_id: String(source.id), gmail_thread_id: String(source.threadId),
  message_id: header('Message-ID') || null, sender, recipients, subject: header('Subject'),
  body_text: plain.join('\n\n'), body_html: html.length ? html.join('\n') : null, received_at: receivedAt.toISOString()
} }];

const batch = $('Préparer lot import').item.json;
const receivedCount = Number($json.received_count);
const importedCount = Number($json.imported_count);
const tasks = Array.isArray($json.classification_tasks) ? $json.classification_tasks : null;
if (!Number.isInteger(receivedCount) || receivedCount !== batch.messages.length) throw new Error('Réponse import incohérente : received_count invalide.');
if (!Number.isInteger(importedCount) || importedCount < 0 || importedCount > receivedCount) throw new Error('Réponse import incohérente : imported_count invalide.');
if (tasks === null || tasks.length > receivedCount) throw new Error('Réponse import incohérente : classification_tasks invalide.');
return [{ json: { _sync: batch._sync, imported_count: importedCount, skipped_not_found: batch.skipped_not_found, classification_tasks: tasks } }];

const preserved = $('Traiter une classification à la fois').item.json;
const statusCode = Number($json.statusCode ?? $json.error?.httpCode ?? 0) || null;
const accepted = $json.error === undefined && (statusCode === null || (statusCode >= 200 && statusCode < 300));
return [{ json: { ...preserved, classification_dispatch_failed: !accepted, classification_status_code: statusCode } }];

const items = $input.all();
const sync = items[0]?.json?._sync;
if (!sync?.user_id || !sync?.execution_id || !sync?.idempotency_key || !sync?.cursor_after || sync.test_mode) throw new Error('Contexte de commit incomplet ou interdit.');
let importedCount = 0;
let skippedNotFound = 0;
for (const item of items) {
  if (Number.isInteger(item.json?.imported_count)) importedCount += item.json.imported_count;
  if (Number.isInteger(item.json?.skipped_not_found)) skippedNotFound += item.json.skipped_not_found;
}
return [{ json: { user_id: sync.user_id, execution_id: sync.execution_id, cursor_before: sync.cursor_before || null, cursor_after: sync.cursor_after, idempotency_key: sync.idempotency_key, imported_count: importedCount, skipped_not_found: skippedNotFound } }];

const items = $input.all();
const sync = items[0]?.json?._sync;
if (!sync?.user_id) throw new Error('Contexte de synchronisation absent du lot.');
const contextKey = (value) => JSON.stringify([
  value?.user_id ?? null,
  value?.execution_id ?? null,
  value?.idempotency_key ?? null,
  value?.cursor_before ?? null,
  value?.cursor_after ?? null,
  value?.test_mode === true,
]);
if (items.some((item) => contextKey(item.json?._sync) !== contextKey(sync))) throw new Error('Contextes de synchronisation mélangés dans le lot.');
const messages = [];
let skippedNotFound = 0;
for (const item of items) {
  const value = item.json || {};
  if (value.skipped_not_found === 1) {
    skippedNotFound += 1;
    continue;
  }
  if (!value.gmail_message_id || !value.gmail_thread_id || !value.sender || !value.received_at) throw new Error('Message normalisé incomplet dans le lot.');
  messages.push({
    gmail_message_id: value.gmail_message_id,
    gmail_thread_id: value.gmail_thread_id,
    message_id: value.message_id ?? null,
    sender: value.sender,
    recipients: Array.isArray(value.recipients) ? value.recipients : [],
    subject: value.subject ?? '',
    body_text: value.body_text ?? '',
    body_html: value.body_html ?? null,
    received_at: value.received_at,
  });
}
if (messages.length > 10) throw new Error('Un lot Gmail ne peut pas dépasser 10 messages.');
return [{ json: { _sync: sync, messages, skipped_not_found: skippedNotFound } }];

const batch = $json;
return batch.classification_tasks.map((task) => ({ json: {
  _sync: batch._sync,
  classification_task: task,
  _batch: { _sync: batch._sync, imported_count: batch.imported_count, skipped_not_found: batch.skipped_not_found }
} }));

const items = $input.all();
const first = items[0]?.json || {};
const batch = first._batch || first;
if (!batch._sync?.user_id) throw new Error('Contexte du lot absent avant la boucle suivante.');
return [{ json: {
  _sync: batch._sync,
  imported_count: Number.isInteger(batch.imported_count) ? batch.imported_count : 0,
  skipped_not_found: Number.isInteger(batch.skipped_not_found) ? batch.skipped_not_found : 0,
} }];
